<script lang="ts">
import { onMount } from 'svelte';
import DeveloperCard from '../../profile/components/DeveloperCard.svelte';
let { onNavigate }: { onNavigate?: (tab:string)=>void } = $props();
let homeElement: HTMLDivElement;
onMount(() => {
 if (window.matchMedia('(prefers-reduced-motion: reduce)').matches || !('IntersectionObserver' in window)) return;
 const observer = new IntersectionObserver(entries => { for (const entry of entries) { if(entry.isIntersecting){ entry.target.classList.add('revealed'); observer.unobserve(entry.target); } } }, {threshold:0.12});
 homeElement.querySelectorAll('section').forEach(section=>observer.observe(section));
 return ()=>observer.disconnect();
});
